const SCENES=[{character:'mint',left:23,top:14,width:29,height:76},{character:'blue',left:52,top:16,width:27,height:74},{character:'blue',left:42,top:18,width:27,height:71}];
const props=[['computer',0,69,52,20],['lamp',1,83,42,12],['headphones',2,61,46,9],['microphone',3,74,45,9],['decor',4,14,64,15]];
export function scene(s){const c=SCENES[s.housing];return `<div class="scene-art" data-home="${s.housing}"><img class="scene-bg" src="./assets/live-room-${s.housing}.webp" width="960" height="640" alt=""><div class="room-sunlight"></div><div class="character-breathe" style="left:${c.left}%;top:${c.top}%;width:${c.width}%;height:${c.height}%"><div class="character-sprite ${c.character}" data-frame="0"></div></div><div class="screen-glimmer"></div><div class="room-props">${props.filter(([slot])=>s.equipped[slot]).map(([slot,frame,x,y,w])=>`<div class="room-prop prop-${slot}" style="left:${x}%;top:${y}%;width:${w}%" data-item="${s.equipped[slot]}"><span style="background-position:${frame%4*100/3}% ${Math.floor(frame/4)*100}%"></span></div>`).join('')}${s.commerce.decorations.includes('starSculpture')?`<div class="room-prop exclusive-prop" style="left:${[70,84,72][s.housing]}%;top:${[45,39,47][s.housing]}%;width:11%"><span style="background-position:66.6667% 100%"></span></div>`:''}</div></div>`;}
/** Coarse pose changes and brief blinks; one timeout at a time. CSS handles breathing on the compositor. */
export class SceneAnimator{constructor(getSettings){this.settings=getSettings;this.reduced=matchMedia('(prefers-reduced-motion: reduce)');this.timeout=null;this.node=null;this.visible=true;this.index=0;this.observer=new IntersectionObserver(entries=>{this.visible=entries[0]?.isIntersecting;this.node?.closest('.scene-art')?.classList.toggle('offscreen',!this.visible);this.schedule();});document.addEventListener('visibilitychange',()=>this.schedule());}
 bind(){const node=document.querySelector('.character-sprite');if(node===this.node)return;this.stop();this.observer.disconnect();this.node=node;if(node){this.observer.observe(node);this.schedule();}this.applySettings();}
 applySettings(){const enabled=this.settings()?.motion!==false&&!this.reduced.matches;document.documentElement.classList.toggle('motion-off',!enabled);document.documentElement.classList.toggle('low-effects',this.settings()?.effects===false||(navigator.hardwareConcurrency||8)<=4);document.documentElement.classList.toggle('scene-paused',document.hidden);if(!enabled)this.stop();else this.schedule();}
 schedule(){this.stop();if(!this.node||!this.visible||document.hidden||this.settings()?.motion===false||this.reduced.matches)return;const sequence=[0,1,0,3,0,2,0,5,0,6,0,7,0,4];const frame=sequence[this.index++%sequence.length];this.node.dataset.frame=frame;this.node.style.backgroundPosition=`${frame%4*100/3}% ${Math.floor(frame/4)*100}%`;this.timeout=setTimeout(()=>this.schedule(),frame===1?120:frame===3?450:frame===0?2600:1100);}
 react(){if(!this.node||this.settings()?.motion===false||this.reduced.matches)return;this.stop();this.node.style.backgroundPosition='100% 0%';this.timeout=setTimeout(()=>this.schedule(),220);}
 stop(){if(this.timeout)clearTimeout(this.timeout);this.timeout=null;}
}
